def design(feats):
    import numpy as np
    from scipy import stats
    X = np.asarray(feats.x, float); y = np.asarray(feats.y, float); n, p = X.shape
    ids = list(feats.ids)
    labs = sorted(set(feats.stratum))
    Z = np.ones((n, 1))
    if len(labs) > 1:
        S = np.array([[s == l for l in labs[1:]] for s in feats.stratum], float)
        Z = np.hstack([Z, S])

    def ll(M):
        b = np.zeros(M.shape[1])
        for _ in range(30):
            eta = np.clip(M @ b, -30, 30); mu = 1 / (1 + np.exp(-eta))
            w = mu * (1 - mu) + 1e-9
            H = M.T @ (M * w[:, None]) + 1e-6 * np.eye(M.shape[1])
            step = np.linalg.solve(H, M.T @ (y - mu)); b += step
            if np.max(np.abs(step)) < 1e-8: break
        mu = np.clip(1 / (1 + np.exp(-np.clip(M @ b, -30, 30))), 1e-12, 1 - 1e-12)
        return float(np.sum(y * np.log(mu) + (1 - y) * np.log(1 - mu)))

    R = np.corrcoef(X, rowvar=False)
    alpha = 0.01 / p
    sel = []
    cap = max(1, min(int(MAX_DRIVERS), 3))
    while len(sel) < cap:
        base = np.hstack([Z, X[:, sel]]); l0 = ll(base); best = None
        for j in range(p):
            if j in sel or any(abs(R[j, k]) >= 0.6 for k in sel): continue
            pv = stats.chi2.sf(2 * (ll(np.hstack([base, X[:, [j]]])) - l0), 1)
            if best is None or pv < best[0]: best = (pv, j)
        if best is None or best[0] > alpha: break
        sel.append(best[1])
    keep = []
    for j in sel:
        others = [k for k in sel if k != j]
        full = np.hstack([Z, X[:, sel]]); red = np.hstack([Z, X[:, others]])
        if stats.chi2.sf(2 * (ll(full) - ll(red)), 1) < alpha: keep.append(j)
    sel = keep
    prods = []
    base = np.hstack([Z, X[:, sel]]); l0 = ll(base)
    npair = p * (p - 1) / 2; bestp = None
    for a in range(p):
        for b in range(a + 1, p):
            if abs(R[a, b]) >= 0.6: continue
            cols = [c for c in (a, b) if c not in sel]
            M = np.hstack([base, X[:, cols], (X[:, a] * X[:, b])[:, None]])
            Mr = np.hstack([base, X[:, cols]])
            pv = stats.chi2.sf(2 * (ll(M) - ll(Mr)), 1)
            if bestp is None or pv < bestp[0]: bestp = (pv, a, b)
    if bestp is not None and bestp[0] < 0.01 / npair:
        _, a, b = bestp; prods = [(ids[a], ids[b])]
        for c in (a, b):
            if c not in sel: sel.append(c)
    drivers = tuple(ids[j] for j in sel)[:int(MAX_DRIVERS)]
    return Design(drivers=drivers, columns=tuple(ids[j] for j in sel),
                  products=tuple(prods), loadings={})

